INSERT INTO sigm.medication_catalog (code, name, presentation, concentration, pharmaceutical_form, route, is_active)
SELECT code, name, presentation, concentration, pharmaceutical_form, route, is_active FROM _seed_ium
ON CONFLICT (code) DO UPDATE SET
    name = EXCLUDED.name,
    presentation = EXCLUDED.presentation,
    concentration = EXCLUDED.concentration,
    pharmaceutical_form = EXCLUDED.pharmaceutical_form,
    route = EXCLUDED.route,
    is_active = EXCLUDED.is_active,
    updated_at = now();

COMMIT;
